mapper.select:
SELECT p.id, p.category_id, p.name, p.sku, p.subtitle, p.main_image, p.price, p.original_price, p.status, p.sales, p.sort, p.create_time, p.update_time, c.name AS category_name, i.available_stock, i.locked_stock, i.total_stock, i.warn_stock FROM product p LEFT JOIN category c ON c.id = p.category_id AND c.deleted = 0 LEFT JOIN inventory i ON i.product_id = p.id WHERE p.deleted = 0
AND p.category_id = #{query.categoryId}
AND p.status = #{query.status}
AND p.price >= #{query.minPrice}
AND p.price <= #{query.maxPrice}
AND (p.name LIKE CONCAT('%', #{query.keyword}, '%') OR p.sku LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY
p.price p.sales p.update_time p.create_time p.sort
ASC DESC
, p.id DESC
